/// # Complexity
///
/// Temporal `O(n)`: one pass over the input, counted in element reads.
/// Spatial `O(1)`: one accumulator word.
pub fn synthetic_heading(x: &[u64]) -> u64 {
    x.iter().sum()
}

/// # Complexity
///
/// Temporal `O(1)` for `n <= 1024` slots: one slot probe per lookup, counted in
/// slot probes; the table never resizes.
/// Spatial `O(1)`: the slot array is fixed at construction.
pub fn synthetic_bounded(n: usize) -> usize {
    n
}

/// # Complexity
///
/// `O(take)` time, `O(1)` extra space.
pub fn synthetic_bare(x: &[i64], take: usize) -> i64 {
    x[0]
}

/// # Complexity
///
/// `O(take)` time, `O(1)` extra space. Accumulates in `i32` with `|x| <= 32*127`.
pub fn synthetic_numerals(x: &[i8], take: usize) -> i32 {
    let mut a = 0i32;
    for v in x.iter().take(take) {
        a += i32::from(*v);
    }
    a
}

/// # Complexity
///
/// Temporal `O(1)`: the three `List.append` recursions traverse 11 cons cells, counted in
/// list links; the shared tail is not traversed.
/// Spatial `O(11)` cons cells for the returned prefix.
pub fn synthetic_numerals_units(rest: &[u64]) -> Vec<u64> {
    rest.to_vec()
}

/// # Complexity
///
/// `O(n_in)` time in exact integer multiply-adds, `O(1)` extra space.
pub fn synthetic_multiply_adds(x: &[i8]) -> i32 {
    x[0] as i32
}

/// # Complexity
///
/// `O(n_in)` time, `O(1)` extra space.
pub fn synthetic_multiply_adds_mutant(x: &[i8]) -> i32 {
    x[0] as i32
}

/// # Complexity
///
/// O(L/8) word compares plus an O(L mod 8) scalar tail, in byte comparisons; spatial O(1).
pub fn synthetic_comparisons(line: &[u8]) -> u64 {
    line[0] as u64
}

/// # Complexity
///
/// O(L/8) time plus an O(L mod 8) tail; spatial O(1).
pub fn synthetic_comparisons_mutant(line: &[u8]) -> u64 {
    digest(line)
}

/// # Complexity
///
/// This is the step path's read: the bytes were read once, so the borrow is O(1) and
/// copies nothing. `O(1)` time and no allocation; the returned slice borrows `self`.
pub fn synthetic_copies(buf: &[u8]) -> &[u8] {
    buf
}

/// # Complexity
///
/// This is the step path's read: the bytes were read once, so the borrow is O(1).
/// `O(1)` time; the returned slice borrows `self`.
pub fn synthetic_copies_mutant(buf: &[u8]) -> &[u8] {
    borrow_range(buf)
}

/// Temporal `O(regions)` payload clones; spatial `O(1)` beyond the regions already
/// reserved.
pub fn synthetic_clones(regions: &[u8]) -> u8 {
    regions[0]
}

/// Temporal `O(regions)`; spatial `O(1)` beyond the regions already reserved.
pub fn synthetic_clones_mutant(regions: &[u8]) -> u8 {
    regions[0]
}

/// `O(M·B·32)` writes and `O(1)` extra space: each weight lane is assigned once.
pub fn synthetic_writes(n: usize) -> usize {
    n
}

/// `O(M·B·32)` assignments and `O(1)` extra space: each weight lane is assigned once.
pub fn synthetic_writes_mutant(n: usize) -> usize {
    n
}

/// `⌈out.len() / chunk⌉` tasks; `O(1)` extra space.
pub fn synthetic_tasks(n: usize) -> usize {
    n
}

/// `⌈out.len() / chunk⌉` chunks; `O(1)` extra space.
pub fn synthetic_tasks_mutant(n: usize) -> usize {
    chunk_count(n)
}

/// Temporal: `O(bytes)` drop of the state; spatial: `O(1)` beyond the freed entry.
pub fn synthetic_drop(bytes: usize) -> usize {
    bytes
}

/// Temporal: `O(bound)` drop of the state; spatial: `O(1)` beyond the freed entry.
pub fn synthetic_drop_mutant(bound: usize) -> usize {
    bound
}

/// Temporal `O(1)` for `n <= 1024` slots, counted in slot probes; the table never
/// resizes. Spatial `O(1)`.
pub fn synthetic_probes(n: usize) -> usize {
    n
}

/// Temporal `O(1)` for `n <= 1024` slots; the slot array is built at construction. Spatial `O(1)`.
pub fn synthetic_probes_mutant(n: usize) -> usize {
    slot_of(n)
}

/// The activation length `n_in` the quantizer was built for (`codes.len()`).
///
/// # Complexity
///
/// `O(1)`.
pub(crate) fn len(&self) -> usize {
    self.codes.len()
}

/// The terminal handle the current staging will publish under, or `None`.
/// Temporal `O(1)`; spatial `O(1)`.
fn staged_handle(&self) -> Option<u32> {
    match &self.staged {
        Some((handle, _)) => Some(*handle),
        None => None,
    }
}

/// Temporal `O(1)`; spatial `O(1)`.
pub fn synthetic_loop(ends: &[usize; 4]) -> usize {
    let mut s = 0;
    while s < 4 {
        s += 1;
    }
    ends[s]
}

/// Temporal `O(1)`; spatial `O(1)`.
pub fn synthetic_call(x: u64) -> u64 {
    finish(mix(x))
}

/// # Complexity
///
/// `O(take)` time, `O(1)` extra space. Accumulates in `Q32.32` with `|x| <= 32·127`.
pub fn synthetic_numerals_free(x: &[i8], take: usize) -> i32 {
    x[0] as i32
}
